"""Pinned sibling checkout contract shared by CI and future app builders."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parents[2]


def configuration(root=ROOT):
    data = json.loads((root / ".github/dependencies.json").read_text())
    if set(data) != {"xgpui", "gpui-luma"}:
        raise ValueError("Expected exactly xgpui and gpui-luma dependency pins")
    for name, pin in data.items():
        if pin["repository"] != f"gpui-luma-dev/{name}":
            raise ValueError(f"Unexpected repository for {name}")
        if not re.fullmatch(r"[0-9a-f]{40}", pin["revision"]):
            raise ValueError(f"{name} must be pinned to a complete commit SHA")
    return data


def fingerprint(root=ROOT):
    digest = hashlib.sha256()
    for name in [".github/dependencies.json", "Cargo.toml",
                 "Cargo.lock", "rust-toolchain.toml"]:
        digest.update(name.encode())
        digest.update((root / name).read_bytes())
    return digest.hexdigest()


def git(path, *args):
    return subprocess.check_output(["git", "-C", str(path), *args], text=True).strip()


def prepare(root=ROOT):
    pins = configuration(root)
    # This command is intentionally for fresh CI checkouts, not dirty developer trees.
    for name, pin in pins.items():
        checkout = root.parent / name
        actual = git(checkout, "rev-parse", "HEAD")
        if actual != pin["revision"]:
            raise ValueError(f"{name}: expected {pin['revision']}, found {actual}")
        if git(checkout, "status", "--porcelain", "--untracked-files=normal"):
            raise ValueError(f"Unexpected dirty dependency checkout: {checkout}")
        print(f"{name}: {pin['repository']} @ {actual}", flush=True)


SDK_PACKAGES = {
    **{name: f"gpui/crates/{folder}" for name, folder in [
        ("xgpui", "gpui"), ("xgpui-apple", "gpui-apple"), ("xgpui-linux", "gpui-linux"),
        ("xgpui-macos", "gpui-macos"), ("xgpui-macros", "gpui-macros"),
        ("xgpui-platform", "gpui-platform"), ("xgpui-web", "gpui-web"),
        ("xgpui-wgpu", "gpui-wgpu"), ("xgpui-windows", "gpui-windows")
    ]},
    **{name: f"extensions/crates/{name}" for name in [
        "xgpui-color", "xgpui-gamut", "xgpui-media", "xgpui-parley", "xgpui-shader", "xgpui-svg"
    ]},
}


def configure_sdk(root=ROOT, sdk=None):
    """Select one checked-out SDK for the app and all transitive Luma consumers.

    This is a build-time source selection, never a runtime application dependency.
    Leave both dependency checkouts unchanged; published Luma declarations resolve
    through the same Cargo patch as the application's direct dependencies.
    """
    sdk = Path(sdk).resolve() if sdk is not None else root.parent / "xgpui"
    lines = ["# Generated by dependencies.py for a fresh pinned CI checkout.", "[patch.crates-io]"]
    for name, relative in SDK_PACKAGES.items():
        manifest = sdk / relative / "Cargo.toml"
        if not manifest.is_file():
            raise ValueError(f"Missing SDK package: {manifest}")
        lines.append(f"{name} = {{ path = {json.dumps(manifest.parent.resolve().as_posix())} }}")
    text = "\n".join(lines) + "\n"
    path = root / ".cargo/config.toml"
    if path.exists() and path.read_text() != text:
        raise ValueError("Refusing to overwrite existing development Cargo configuration")
    path.parent.mkdir(exist_ok=True)
    path.write_text(text)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["outputs", "prepare", "configure"])
    parser.add_argument("--sdk", type=Path, help="SDK worktree for local configure")
    args = parser.parse_args()
    if args.sdk is not None and args.command != "configure":
        parser.error("--sdk applies only to configure")
    if args.command == "configure":
        configure_sdk(sdk=args.sdk)
        return
    if args.command == "prepare":
        prepare()
        configure_sdk()
        return
    values = {f"{name}-{key}": value for name, pin in configuration().items()
              for key, value in pin.items()}
    values["cache-key"] = fingerprint()
    text = "".join(f"{key}={value}\n" for key, value in values.items())
    if output := os.environ.get("GITHUB_OUTPUT"):
        with open(output, "a", encoding="utf-8") as file:
            file.write(text)
    print(text, end="")


if __name__ == "__main__":
    main()
